import django.db.models.deletion


def create_specimens(apps, schema_editor):
    LabQueue = apps.get_model("laboratory", "LabQueue")
    LabOrderItem = apps.get_model("laboratory", "LabOrderItem")
    LabResult = apps.get_model("laboratory", "LabResult")
    Specimen = apps.get_model("laboratory", "Specimen")

    status_map = {
        "PENDING": "PENDING",
        "COLLECTED": "COLLECTED",
        "PROCESSING": "PROCESSING",
        "REVIEW": "PROCESSING",
        "RELEASED": "PROCESSING",
    }

    for queue in LabQueue.objects.select_related("lab_order").iterator():
        if getattr(queue, "specimen_id", None):
            continue

        first_item = (
            LabOrderItem.objects.filter(lab_order=queue.lab_order)
            .select_related("test")
            .first()
        )
        specimen_type = queue.sample_type or (
            first_item.test.specimen_type if first_item else "BLOOD"
        )
        barcode = queue.sample_id or queue.queue_number

        specimen = Specimen.objects.create(
            barcode=barcode,
            specimen_type=specimen_type,
            lab_order=queue.lab_order,
            collected_by=queue.collected_by,
            collected_at=queue.collected_at,
            status=status_map.get(queue.queue_status, "PENDING"),
            rejection_reason=queue.rejection_reason,
        )
        specimen.order_items.add(*LabOrderItem.objects.filter(lab_order=queue.lab_order))

        queue.specimen_id = specimen.id
        queue.save(update_fields=["specimen"])

    for result in LabResult.objects.select_related("order_item").filter(specimen__isnull=True):
        queue = LabQueue.objects.filter(lab_order=result.order_item.lab_order).first()
        if queue and queue.specimen_id:
            result.specimen_id = queue.specimen_id
            result.save(update_fields=["specimen"])


